import React, { useEffect, useRef, useState } from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import images from "../images";
import Icon from "../components/icon";
import caretLeft from "../../static/caret_left.png";
import caretRight from "../../static/caret_right.png";
import classNames from "classnames";

const Carousel: React.FC = () => {
  const { t } = useTranslation();
  const items = t("carousel.items", { returnObjects: true }) as {
    image: string;
    subtitle: string;
    description: string;
  }[];
  const isMobile = typeof window !== 'undefined' && window.innerWidth <= 768;

  const [index, setIndex] = useState(0);
  const [hovered, setHovered] = useState(false);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);
  const groupSize = isMobile ? 1 : 4;

  const totalGroups = Math.ceil(items.length / groupSize);

  const resetTimeout = () => {
    if (timeoutRef.current) {
      clearTimeout(timeoutRef.current);
    }
  };

  useEffect(() => {
    if (!hovered) {
      timeoutRef.current = setTimeout(() => {
        setIndex((prevIndex) => (prevIndex + 1) % totalGroups);
      }, 4000);
    }
    return () => resetTimeout();
  }, [index, hovered]);

  const handlePrev = () => {
    resetTimeout();
    setIndex((prevIndex) => (prevIndex - 1 + totalGroups) % totalGroups);
  };

  const handleNext = () => {
    resetTimeout();
    setIndex((prevIndex) => (prevIndex + 1) % totalGroups);
  };

  return (
    <div className="relative">
    <section
      className="relative overflow-hidden w-full max-w-[1760px] mx-auto"
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      >
      <div
        className="flex transition-transform duration-700 ease-in-out w-full"
        style={{ transform: `translateX(-${index * 100}%)`
        // , width: `${50 * totalGroups}%` 
    }}
    >
        {[...Array(totalGroups)].map((_, groupIdx) => (
            <div
            key={groupIdx}
            className="flex flex-shrink-0 w-full"
            >
            {items.slice(groupIdx * groupSize, groupIdx * groupSize + groupSize).map((item, i) => (
                <div key={i} className="relative w-full">
                <img
                  src={images[item.image].src}
                  alt={images[item.image].alt}
                  className="object-cover w-full h-[450px]"
                  />
                <div className="bottom-0  text-DarkGreen p-4">
                <div className="w-4 my-4">
                  <Icon fill="#232B22" />
                </div>
                  <h4 className="subheader-2">{item.subtitle}</h4>
                  <p className="body">{item.description}</p>
                </div>
              </div>
            ))}
          </div>
        ))}
      </div>

      {/* Arrows */}
      {/* <button
        className="absolute left-2 top-1/2 -translate-y-1/2 opacity-50 hover:opacity-0 transition"
        onClick={handlePrev}
        >
        <img src={caretLeft} alt="Previous" className="w-8 h-8" />
        </button>
        <button
        className="absolute -right-2 top-1/2 -translate-y-1/2 opacity-50 hover:opacity-0 transition"
        onClick={handleNext}
        >
        <img src={caretRight} alt="Next" className="w-8 h-8" />
        </button> */}

      {/* Dots */}
        <div className="flex justify-center gap-2 mt-4">
        {[...Array(totalGroups)].map((_, dotIdx) => (
            <button
            key={dotIdx}
            onClick={() => setIndex(dotIdx)}
            className={classNames(
                "w-3 h-3 rounded-full transition duration-300",
                {
                    "bg-DarkGreen": index === dotIdx,
                    "bg-DarkGrayText/50": index !== dotIdx,
                }
            )}
            aria-label={`Go to slide ${dotIdx + 1}`}
            />
        ))}
        </div>

    </section>
          <button
        className="absolute left-2 sm:-left-8 top-1/2 -translate-y-1/2 opacity-50 hover:opacity-100 transition"
        onClick={handlePrev}
      >
        <img src={caretLeft} alt="Previous" className="w-4" />
      </button>
      <button
        className="absolute right-2 sm:right-8 top-1/2 -translate-y-1/2 opacity-50 hover:opacity-100 transition"
        onClick={handleNext}
      >
        <img src={caretRight} alt="Next" className="w-4" />
      </button>
        </div>
  );
};

export default Carousel;
